		"**天机化权** 在官禄：",
		"官禄宫天机，最适合策划、IT、咨询顾问、教育培训、宗教哲学、媒体等需要智慧与变通的行业，擅长运筹帷幄、出谋划策。不宜独立创业单打独斗，在大平台中最能发挥才智；若化权则可独当一面，但仍多变动，需稳定心性；职业中易有转换，应将变动化为积累，而非重头再来。",
		"▶ 化权：化权，在策划咨询或技术领域有话语权，多变的特质化为强烈的掌控力，执行力提升。",
