		"**天梁** 在官禄：",
		"官禄宫天梁，适合法律、医学、教育、宗教、政府监察、慈善等需要权威与学识的领域。在午宫入庙，主一品武官，军警法官最为显贵；化权则权威大增，在专业领域极有话语权；化科则名声并茂，是非常理想的学术型或专业型职业格局。",
		"✦ **天钺**：事业关键时刻有女性上司或前辈提携。",
		"  （空宫，借对宫福德：天同、巨门入事）",
