		"✦ **文曲**：事业以演讲、艺术、咨询、媒体见长。",
		"**武曲** 在迁移：",
		"迁移宫武曲，外出能干，靠实力在外地打拼，适合在财务、工程、军警等领域闯荡他方；外出实干派，不依赖人脉靠实力立足。化禄则外出大财；化忌则外出有意外或血光风险，需购保险。",
		"✦ **右弼**：异地贵人扶持明显。",
		"✦ **天马**：天马在迁移最喜，外出远方大吉。",
		"🔴 **廉贞化忌**（落福德）→ 精神层面多阴郁，内心福分受损，需主动寻找精神出口",
		"◇ **天魁在子女**：儿子贵气或男性晚辈助力",
